package com.nostrvault.service

import androidx.exifinterface.media.ExifInterface
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File
import java.util.Base64

class MediaPrivacyTest {
    // 2×2 JPEGs made with macOS sips, tagged with exiftool: Make=Motorola and a
    // location at 39.33 N, 82.98 W, in EXIF GPS in one and XMP only in the other.
    private val exifGpsJpeg = ""
    private val xmpGpsJpeg = ""

    private fun file(b64: String, ext: String = ".jpg"): File = File.createTempFile("privacy_", ext).apply {
        writeBytes(Base64.getDecoder().decode(b64))
        deleteOnExit()
    }

    @Test fun xmpLocationIsFound() {
        assertTrue(MediaPrivacy.xmpHasLocation("""<rdf:Description exif:GPSLatitude="39,20.1N"/>"""))
        assertFalse(MediaPrivacy.xmpHasLocation("""<rdf:Description xmp:CreatorTool="Camera"/>"""))
        assertFalse(MediaPrivacy.xmpHasLocation(null))
    }

    @Test fun exifLocationIsRemovedAndTheRestKept() {
        val f = file(exifGpsJpeg)
        assertTrue("positive control: the test photo has a location", MediaPrivacy.imageHasLocation(ExifInterface(f)))

        assertTrue(MediaPrivacy.removeLocation(f, "image/jpeg"))
        val after = ExifInterface(f)
        assertFalse(MediaPrivacy.imageHasLocation(after))
        assertEquals("Motorola", after.getAttribute(ExifInterface.TAG_MAKE))
    }

    @Test fun xmpLocationIsRemoved() {
        val f = file(xmpGpsJpeg)
        assertTrue("positive control: the XMP has a location", MediaPrivacy.imageHasLocation(ExifInterface(f)))

        assertTrue(MediaPrivacy.removeLocation(f, "image/jpeg"))
        assertFalse(MediaPrivacy.imageHasLocation(ExifInterface(f)))
        assertFalse(String(f.readBytes(), Charsets.ISO_8859_1).contains("GPSLatitude"))
    }

    @Test fun aPhotoWithoutLocationIsLeftByteForByte() {
        val f = file(exifGpsJpeg)
        MediaPrivacy.removeLocation(f, "image/jpeg")
        val clean = f.readBytes()
        assertTrue(MediaPrivacy.removeLocation(f, "image/jpeg"))
        assertArrayEquals(clean, f.readBytes())
    }

    @Test fun otherFilesPassThrough() {
        val f = File.createTempFile("privacy_", ".txt").apply { writeText("hello"); deleteOnExit() }
        assertTrue(MediaPrivacy.removeLocation(f, "text/plain"))
        assertEquals("hello", f.readText())
    }
}
